mapper.select:
SELECT id AS id, name AS name, calc_type AS calc_type, cycle AS cycle
FROM fee_item
WHERE item_code = #{itemCode}

SELECT btrim(b.period) AS period, coalesce(h.usage_type, '未知') AS usage, coalesce(sum(b.payable), 0) AS billed, coalesce(sum(b.paid_amount), 0) AS received, coalesce(sum(b.waive_amount), 0) AS waived FROM bill b JOIN fee_item f ON f.id = b.item_id LEFT JOIN house h ON h.tenant_id = b.tenant_id AND h.house_id = b.house_id WHERE b.deleted_at IS NULL AND b.status <> '已作废' AND b.period >= #{fromPeriod} AND b.period <= #{toPeriod} AND f.item_code = #{itemCode}
AND b.community_id = #{communityId}
GROUP BY btrim(b.period), coalesce(h.usage_type, '未知') ORDER BY 1, 2

SELECT count(*)
FROM bill b
JOIN fee_item f ON f.id = b.item_id
WHERE b.deleted_at IS NULL
  AND b.status <> '已作废'
  AND b.period >= #{fromPeriod}
  AND b.period <= #{toPeriod}
  AND f.item_code = #{itemCode}
  AND b.payable - b.waive_amount - b.paid_amount < 0

  AND b.community_id = #{communityId}

SELECT coalesce(sum(p.amount), 0)
FROM payment p
WHERE p.status = '正常'
  AND p.method <> '预存抵扣'
  AND p.paid_at >= #{fromTs}
  AND p.paid_at <  #{toTs}
  AND EXISTS (
      SELECT 1 FROM payment_allocation a
      JOIN fee_item f ON f.id = a.item_id
      WHERE a.payment_id = p.id AND f.item_code = #{itemCode}
  )

  AND p.community_id = #{communityId}
